item.aggregated_output:
    const size_t ns_in_sec = 10000000;
    const uint64_t sec_to_unix = 11644473600LL;
    return win_time / ns_in_sec - sec_to_unix;
}

static int parse_htime_item(struct archive_read* a, char unix_time,
        uint64_t* where, ssize_t* extra_data_size)
{
    if(unix_time) {
        uint32_t time_val;
        if(!read_u32(a, &time_val))
            return ARCHIVE_EOF;

        *extra_data_size -= 4;
        *where = (uint64_t) time_val;
    } else {
        uint64_t windows_time;
        if(!read_u64(a, &windows_time))
            return ARCHIVE_EOF;

        *where = time_win_to_unix(windows_time);
        *extra_data_size -= 8;
    }

    return ARCHIVE_OK;
}

static int parse_file_extra_htime(struct archive_read* a,
        struct archive_entry* e, struct rar5* rar,
        ssize_t* extra_data_size)
{
    char unix_time = 0;
    size_t flags;
    size_t value_len;

    enum HTIME_FLAGS {
        IS_UNIX       = 0x01,
        HAS_MTIME     = 0x02,
        HAS_CTIME     = 0x04,
        HAS_ATIME     = 0x08,
        HAS_UNIX_NS   = 0x10,
    };

    if(!read_var_sized(a, &flags, &value_len))
        return ARCHIVE_EOF;

    *extra_data_size -= value_len;
    if(ARCHIVE_OK != consume(a, value_len)) {
        return ARCHIVE_EOF;
    }

    unix_time = flags & IS_UNIX;

    if(flags & HAS_MTIME) {
        parse_htime_item(a, unix_time, &rar->file.e_mtime, extra_data_size);
        archive_entry_set_mtime(e, rar->file.e_mtime, 0);
    }

    if(flags & HAS_CTIME) {
        parse_htime_item(a, unix_time, &rar->file.e_ctime, extra_data_size);
        archive_entry_set_ctime(e, rar->file.e_ctime, 0);
    }

    if(flags & HAS_ATIME) {
        parse_htime_item(a, unix_time, &rar->file.e_atime, extra_data_size);
        archive_entry_set_atime(e, rar->file.e_atime, 0);
    }

    if(flags & HAS_UNIX_NS) {
        if(!read_u32(a, &rar->file.e_unix_ns))
            return ARCHIVE_EOF;

        *extra_data_size -= 4;
    }

    return ARCHIVE_OK;
}

static int parse_file_extra_redir(struct archive_read* a,
        struct archive_entry* e, struct rar5* rar,
        ssize_t* extra_data_size)
{
	size_t value_len = 0;
	char target_utf8_buf[2048 * 4];
	const uint8_t* p;

	if(!read_var_sized(a, &rar->file.redir_type, &value_len))
		return ARCHIVE_EOF;
	if(ARCHIVE_OK != consume(a, value_len))
		return ARCHIVE_EOF;
	*extra_data_size -= value_len;

	if(!read_var_sized(a, &rar->file.redir_flags, &value_len))
		return ARCHIVE_EOF;
	if(ARCHIVE_OK != consume(a, value_len))
		return ARCHIVE_EOF;
	*extra_data_size -= value_len;

	if(!read_var_sized(a, &value_len, NULL))
		return ARCHIVE_EOF;
        *extra_data_size -= value_len + 1;
	if(!read_ahead(a, value_len, &p))
		return ARCHIVE_EOF;

	if(value_len > 2047) {
		archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
		    "Link target is too long");
		return ARCHIVE_FATAL;
	}
	if(value_len == 0) {
		archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
		    "No link target specified");
		return ARCHIVE_FATAL;
	}
	memcpy(target_utf8_buf, p, value_len);
	target_utf8_buf[value_len] = 0;

	if(ARCHIVE_OK != consume(a, value_len))
		return ARCHIVE_EOF;

	switch(rar->file.redir_type) {
		case REDIR_TYPE_UNIXSYMLINK:
		case REDIR_TYPE_WINSYMLINK:
			archive_entry_set_filetype(e, AE_IFLNK);
			archive_entry_update_symlink_utf8(e, target_utf8_buf);
			if (rar->file.redir_flags & REDIR_SYMLINK_IS_DIR) {
				archive_entry_set_symlink_type(e,
				    AE_SYMLINK_TYPE_DIRECTORY);
			} else {
				archive_entry_set_symlink_type(e,
			    AE_SYMLINK_TYPE_FILE);
			}
			break;

		case REDIR_TYPE_HARDLINK:
			archive_entry_set_filetype(e, AE_IFREG);
			archive_entry_update_hardlink_utf8(e, target_utf8_buf);
			break;

		default:
			/* Unknown redir type */
			if(ARCHIVE_OK != consume(a, value_len))
				return ARCHIVE_EOF;
			archive_set_error(&a->archive,
			    ARCHIVE_ERRNO_FILE_FORMAT,
			    "Unsupported redir type: %ld",
			    rar->file.redir_type);
			return ARCHIVE_FATAL;
			break;
	}
	return ARCHIVE_OK;
}

static int parse_file_extra_owner(struct archive_read* a,
        struct archive_entry* e, ssize_t* extra_data_size)
{
	uint64_t flags = 0;
	size_t value_len = 0;
	size_t name_len = 0;
	size_t id = 0;
	char namebuf[OWNER_MAXNAMELEN];
	const uint8_t* p;

	if(!read_var_sized(a, &flags, &value_len))
		return ARCHIVE_EOF;
	if(ARCHIVE_OK != consume(a, value_len))
		return ARCHIVE_EOF;
	*extra_data_size -= value_len;

	if ((flags & OWNER_USER_NAME) != 0) {
		if(!read_var_sized(a, &value_len, NULL))
			return ARCHIVE_EOF;
	        *extra_data_size -= value_len + 1;
		if(!read_ahead(a, value_len, &p))
			return ARCHIVE_EOF;
		if (value_len > OWNER_MAXNAMELEN)
			name_len = OWNER_MAXNAMELEN;
		else
			name_len = value_len;
		memcpy(namebuf, p, name_len);
		namebuf[name_len] = 0;
		namebuf[name_len] = 0;
		if(ARCHIVE_OK != consume(a, value_len))
			return ARCHIVE_EOF;

		archive_entry_set_uname(e, namebuf);
	}
	if ((flags & OWNER_GROUP_NAME) != 0) {
		if(!read_var_sized(a, &value_len, NULL))
			return ARCHIVE_EOF;
	        *extra_data_size -= value_len + 1;
		if(!read_ahead(a, value_len, &p))
			return ARCHIVE_EOF;
		if (value_len > OWNER_MAXNAMELEN)
			name_len = OWNER_MAXNAMELEN;
		else
			name_len = value_len;
		memcpy(namebuf, p, name_len);
		namebuf[name_len] = 0;
		if(ARCHIVE_OK != consume(a, value_len))
			return ARCHIVE_EOF;

		archive_entry_set_gname(e, namebuf);
	}
	if ((flags & OWNER_USER_UID) != 0) {
		if(!read_var_sized(a, &id, &value_len))
			return ARCHIVE_EOF;
		if(ARCHIVE_OK != consume(a, value_len))
			return ARCHIVE_EOF;
		*extra_data_size -= value_len;

		archive_entry_set_uid(e, id);
	}
	if ((flags & OWNER_GROUP_GID) != 0) {
		if(!read_var_sized(a, &id, &value_len))
			return ARCHIVE_EOF;
		if(ARCHIVE_OK != consume(a, value_len))
			return ARCHIVE_EOF;
		*extra_data_size -= value_len;

		archive_entry_set_gid(e, id);
	}
	return ARCHIVE_OK;
}

static int process_head_file_extra(struct archive_read* a,
        struct archive_entry* e, struct rar5* rar,
        ssize_t extra_data_size)
{
    size_t extra_field_size;
    size_t extra_field_id = 0;
    int ret = ARCHIVE_FATAL;
    size_t var_size;

    while(extra_data_size > 0) {
        if(!read_var_sized(a, &extra_field_size, &var_size))
            return ARCHIVE_EOF;

        extra_data_size -= var_size;
        if(ARCHIVE_OK != consume(a, var_size)) {
            return ARCHIVE_EOF;
        }

        if(!read_var_sized(a, &extra_field_id, &var_size))
            return ARCHIVE_EOF;

        extra_data_size -= var_size;
        if(ARCHIVE_OK != consume(a, var_size)) {
            return ARCHIVE_EOF;
        }

        switch(extra_field_id) {
            case EX_HASH:
                ret = parse_file_extra_hash(a, rar, &extra_data_size);
                break;
            case EX_HTIME:
                ret = parse_file_extra_htime(a, e, rar, &extra_data_size);
                break;
            case EX_REDIR:
		ret = parse_file_extra_redir(a, e, rar, &extra_data_size);
		break;
            case EX_UOWNER:
		ret = parse_file_extra_owner(a, e, &extra_data_size);
		break;
            case EX_CRYPT:
                /* fallthrough */
            case EX_VERSION:
                /* fallthrough */
            case EX_SUBDATA:
                /* fallthrough */
            default:
                archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                        "Unknown extra field in file/service block: 0x%x",
                        (int) extra_field_id);
                return ARCHIVE_FATAL;
        }
    }

    if(ret != ARCHIVE_OK) {
        /* Attribute not implemented. */
        return ret;
    }

    return ARCHIVE_OK;
}

